export function normalizeHost(value) {
  if (typeof value !== "string" || !value.trim()) {
    throw new TypeError("host must be a non-empty string");
  }
  return value.trim();
}

export function requireCandidate(candidates, id) {
  const candidate = candidates.find((item) => item.id === id);
  if (!candidate) throw new Error("unknown candidate: " + id);
  return candidate;
}

export function requireActive(model) {
  if (model.state !== "active") throw new Error("active model required");
  return model;
}

export function verifyCheckpointRef(ref) {
  if (!/^sha256:[a-f0-9]{64}$/.test(ref)) {
    throw new Error("invalid checkpoint reference");
  }
  return ref;
}

export async function loadJson(path) {
  const content = await readFile(path, "utf8");
  return JSON.parse(content);
}

export async function saveJson(path, data) {
  await writeFile(path, JSON.stringify(data, null, 2) + "\n");
}

export function jsonResponse(res, body) {
  res.writeHead(200, {"content-type": "application/json; charset=utf-8"});
  res.end(JSON.stringify(body));
}

export function routeTask(models, task) {
  const eligible = models.filter((model) =>
    model.state === "active" && model.tasks.includes(task)
  );
  return chooseByPriority(eligible);
}

export function verifyOrigin(model) {
  if (model.origin !== "hercules-native") {
    throw new Error("external model rejected");
  }
  return model;
}

export function safeInteger(value, fallback) {
  const number = Number(value);
  return Number.isInteger(number) ? number : fallback;
}

export function percentage(part, total) {
  return total ? part / total : 0;
}

export function minimumGate(value, threshold) {
  if (value < threshold) throw new Error("minimum threshold missed");
  return value;
}

