  assert.notEqual(candidate.checkpoint, active.checkpoint);
  assert.equal(candidate.state, "candidate");
  assert.equal(active.state, "active");
});

test("unauthorized request is rejected", async () => {
  const response = await fetch(base + "/v1/models");
  assert.equal(response.status, 401);
});

test("health reports active model count", async () => {
  const response = await fetch(base + "/health");
  const body = await response.json();
  assert.equal(body.active, 8);
});

export function sourceCommit(value) {
  if (!/^[a-f0-9]{40}$/.test(value)) {
    throw new TypeError("source commit must be a git sha");
  }
  return value;
}

export function artifactDigest(bytes) {
  return createHash("sha256").update(bytes).digest("hex");
}

export function runtimeMap(entries) {
  return Object.fromEntries(entries.map(([id, runtime]) => [id, runtime]));
}

export function ensureCandidateMode(enabled) {
  if (!enabled) {
    const error = new Error("candidate evaluation is disabled");
    error.statusCode = 403;
    throw error;
  }
}

export async function withServer(server, work) {
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  try {
    return await work(server.address());
  } finally {
    await new Promise((resolve) => server.close(resolve));
  }
}
